public class TranslateScalePainterTest {
    static int failures = 0;

    static void check(String label, Object expected, Object actual) {
        if (java.util.Objects.equals(expected, actual)) {
            System.out.println("PASS  " + label);
        } else {
            System.out.println("FAIL  " + label + " -- expected " + expected + " but got " + actual);
            failures++;
        }
    }

    static String pixel(java.awt.image.BufferedImage img, int x, int y) {
        if (img == null) {
            return "null-image";
        }
        return String.format("#%06X", img.getRGB(x, y) & 0xFFFFFF);
    }

    static java.awt.image.BufferedImage render(int width, int height, int tx, int ty, double factor) {
        java.awt.image.BufferedImage img = new java.awt.image.BufferedImage(
                width, height, java.awt.image.BufferedImage.TYPE_INT_RGB);
        java.awt.Graphics2D g = img.createGraphics();
        try {
            TranslateScalePainter.paint(g, width, height, tx, ty, factor);
        } finally {
            g.dispose();
        }
        return img;
    }

    public static void main(String[] args) {
        try {
            java.awt.image.BufferedImage a = render(80, 60, 20, 10, 3.0);
            java.awt.image.BufferedImage b = render(60, 60, 0, 0, 1.0);
            check("scaled square near its top-left (25,15)", "#0000FF", pixel(a, 25, 15));
            check("scaled square near its bottom-right (45,35)", "#0000FF", pixel(a, 45, 35));
            check("white to the right of the square (55,20)", "#FFFFFF", pixel(a, 55, 20));
            check("white left of the translated origin (10,20)", "#FFFFFF", pixel(a, 10, 20));
            check("white above the translated origin (30,5)", "#FFFFFF", pixel(a, 30, 5));
            check("red marker after the transform is undone (77,57)", "#FF0000", pixel(a, 77, 57));
            check("identity transform leaves a 10x10 square (5,5)", "#0000FF", pixel(b, 5, 5));
            check("nothing at (15,5) with factor 1.0", "#FFFFFF", pixel(b, 15, 5));
        } catch (Exception e) {
            failures++;
            System.out.println("FAIL  unexpected exception: " + e);
        }
        if (failures > 0) {
            System.out.println(failures + " test(s) failed.");
            System.exit(1);
        }
        System.out.println("ALL TESTS PASSED");
    }
}

